export const places={tampines:{name:'Tampines Central',station:'Tampines',code:'DT32 / EW2',coord:[103.9447,1.3559],walk:5},bedok:{name:'Bedok Mall',station:'Bedok',code:'EW5',coord:[103.9291,1.3240],walk:4},paya:{name:'Paya Lebar Quarter',station:'Paya Lebar',code:'EW8',coord:[103.8924,1.3177],walk:4},raffles:{name:'One Raffles Place',station:'Raffles Place',coord:[103.8515,1.2843],walk:4},bugis:{name:'Bugis Junction',station:'Bugis',coord:[103.8555,1.2990],walk:3},chinatown:{name:'Chinatown Point',station:'Chinatown',coord:[103.8447,1.2852],walk:3}};
export const scenarios={disruption:{name:'Signal fault',label:'DISRUPTION REPLAY',delay:20,rain:true,crowd:'high',description:'An injected EWL signal fault between Paya Lebar and Kallang. Not a current service advisory.'},normal:{name:'An ordinary morning',label:'NORMAL DAY REPLAY',delay:0,rain:false,crowd:'medium',description:'Normal service. A minor delay should not create an unnecessary interruption.'},minor:{name:'A small delay',label:'MINOR DELAY REPLAY',delay:4,rain:false,crowd:'medium',description:'A four-minute EWL delay. Keep the usual route if the arrival buffer is sufficient.'},rain:{name:'A sudden downpour',label:'WEATHER REPLAY',delay:0,rain:true,crowd:'high',description:'Heavy rain adds uncertainty to outdoor walking and increases the comfort penalty for exposed legs.'},planned:{name:'Tomorrow’s planned works',label:'PLANNED WORKS REPLAY',delay:25,rain:false,crowd:'high',description:'A synthetic planned EWL reduced-frequency window, 07:00–09:00 tomorrow, affecting the same corridor.'}};
export const clockMinutes=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};
export const formatTime=n=>{n=((n%1440)+1440)%1440;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
const dtlEast=[[103.943,1.3455],[103.9384,1.3417],[103.9323,1.3365],[103.9166,1.335],[103.9081,1.3347],[103.8994,1.3364],[103.8902,1.335],[103.8796,1.3268],[103.8715,1.3213],[103.8629,1.3137],[103.8622,1.3056],[103.8558,1.3007]];
const ewlEast=[[103.9534,1.3273],[103.9464,1.327],[103.9295,1.3239],[103.9129,1.321],[103.9032,1.3198],[103.8923,1.3178],[103.8829,1.3115],[103.8714,1.3074],[103.8627,1.3071],[103.8558,1.3007]];
const city=[[103.8526,1.2932],[103.8512,1.2841]];
function routeGeometry(origin,destination,kind){let points=[places[origin].coord];if(kind==='usual'){points.push(...ewlEast.slice(origin==='tampines'?0:origin==='bedok'?2:5));}else if(origin==='tampines'){points.push(...dtlEast);}else{points.push([103.8923,1.3178],[103.8796,1.3268],...dtlEast.slice(8));}if(destination==='raffles'){points.push(...(kind==='direct'?[[103.8609,1.2925],[103.8585,1.2794],[103.8529,1.2796]]:city));}else if(destination==='chinatown'){points.push(...(kind==='usual'?[...city,[103.8455,1.2803]]:[[103.8609,1.2925],[103.8585,1.2794],[103.8529,1.2796],[103.8486,1.2819]]));}points.push(places[destination].coord);return points;}
export function planJourney({origin='tampines',destination='raffles',departure='07:40',deadline='08:45',scenario='disruption',comfort=false,threshold=10}={}){
 if(!places[origin]||!['tampines','bedok','paya'].includes(origin)||!['raffles','bugis','chinatown'].includes(destination)||!scenarios[scenario])throw new Error('Choose one of the supported demo journeys.');
 if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(departure)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(deadline)||![5,10,15].includes(Number(threshold)))throw new Error('Choose a valid time and alert threshold.');
 const start=clockMinutes(departure),plannedOverlap=scenario==='planned'&&start<540&&start+75>420;
 const event={...scenarios[scenario]};if(scenario==='planned'&&!plannedOverlap){event.delay=0;event.crowd='medium';}
 let due=clockMinutes(deadline);if(due<start)due+=1440;
 const base={tampines:{raffles:[45,49,54],bugis:[40,44,47],chinatown:[49,52,55]},bedok:{raffles:[35,49,55],bugis:[30,43,47],chinatown:[39,52,55]},paya:{raffles:[26,39,43],bugis:[21,32,36],chinatown:[30,42,45]}}[origin][destination];
 const routes=['usual','balanced','direct'].map((id,i)=>{const dt=id!=='usual',wet=event.rain?(id==='direct'?4:1):0,min=base[i]+(dt?0:event.delay)+wet,max=min+(dt?3:5),arrival=start+max,buffer=due-arrival,crowd=dt?(id==='direct'?'low':'medium'):event.crowd;
 let lines=dt?(origin==='tampines'?['DTL']:origin==='paya'?['CCL','DTL']:['EWL','CCL','DTL']):['EWL'];if(id==='balanced'&&destination==='raffles')lines.push('EWL');if(!dt&&destination==='chinatown')lines.push('NEL');
 const walk=places[origin].walk+(id==='direct'&&destination==='raffles'?10:places[destination].walk);
 const steps=[{title:`Walk from ${places[origin].name}`,detail:`To ${places[origin].station} station · use signed pedestrian crossings`,minutes:places[origin].walk,type:'walk'},{title:dt?(origin==='tampines'?'Board the Downtown Line':'Take EWL to Paya Lebar, CCL to MacPherson, then DTL'):`Board EWL toward Tuas Link`,detail:dt?(origin==='tampines'?`DT32 Tampines · toward Bukit Panjang · alight at ${id==='balanced'&&destination==='raffles'?'Bugis':destination==='raffles'?'Downtown':places[destination].station}`:'Change at Paya Lebar and MacPherson; follow platform direction signs'):`${places[origin].code} · alight at ${destination==='chinatown'?'Outram Park':places[destination].station}${event.delay?' · additional delay included':''}`,minutes:Math.max(1,min-walk-(id==='balanced'&&destination==='raffles'?9:0)),type:'rail'}];
 if(id==='balanced'&&destination==='raffles')steps.push({title:'Change at Bugis to the East–West Line',detail:'Toward Tuas Link · 2 stops to Raffles Place; avoids the affected eastern segment',minutes:9,type:'rail'});
 if(dt&&origin==='paya'){steps[1].title='Take CCL to MacPherson, then change to DTL';steps[1].detail='CCL toward HarbourFront, then DTL toward Bukit Panjang. Follow platform direction signs.';}
 if(!dt&&destination==='chinatown'){steps[1].minutes-=6;steps.push({title:'At Outram Park, change to the North East Line',detail:'Toward Punggol Coast · 1 stop to Chinatown',minutes:6,type:'rail'});}
 steps.push({title:`Walk to ${places[destination].name}`,detail:'Follow street signs to your destination. Shelter and lift availability are not verified.',minutes:walk-places[origin].walk,type:'walk'});
 const penalty=(comfort?{low:0,medium:6,high:15}:{low:0,medium:1,high:2})[crowd];return {id,name:id==='usual'?'Your usual way':id==='balanced'?'The balanced way':'A little more breathing room',lines,min,max,arrival,buffer,crowd,walk,steps,geometry:routeGeometry(origin,destination,id),score:max+penalty+Math.max(0,-buffer)*4,delay:dt?0:event.delay};});
 const ranked=[...routes].sort((a,b)=>a.score-b.score);let best=ranked[0];const usual=routes[0];if(!comfort&&usual.buffer>=threshold&&usual.max<=best.max+5)best=usual;
 const interrupted=usual.buffer<threshold||plannedOverlap;return {routes,best,usual,event,start,due,interrupted,latestLeave:due-best.max,notice:!interrupted?'Your usual journey still protects your arrival. No interruption needed.':best.buffer<0?'All options miss your deadline. Leave earlier if possible.':`Switch to ${best.lines.includes('DTL')?'the Downtown Line':'your usual route'} to protect your arrival.`};
}
